  `evidence` TEXT COLLATE NOCASE NOT NULL DEFAULT (json_object()) CONSTRAINT `ck_json_evidence` CHECK (json_valid(`evidence`)),
  `model_version_id` TEXT COLLATE NOCASE CONSTRAINT `ck_len_model_version_id` CHECK (length(`model_version_id`) <= 36),
  `created_at` INTEGER NOT NULL DEFAULT (CAST(unixepoch('subsec')*1000 AS INTEGER)),
  UNIQUE (`track_id`, `player_id`, `model_version_id`)
) STRICT;
CREATE TABLE `track_identity_decisions` (
  `id` TEXT COLLATE NOCASE PRIMARY KEY CONSTRAINT `ck_len_id` CHECK (length(`id`) <= 36),
  `track_id` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_len_track_id` CHECK (length(`track_id`) <= 36),
  `player_id` TEXT COLLATE NOCASE CONSTRAINT `ck_len_player_id` CHECK (length(`player_id`) <= 36),
  `state` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_enum_state` CHECK (`state` IN ('UNRESOLVED', 'CANDIDATE', 'CONFIRMED', 'REJECTED', 'CONFLICT')),
  `decided_by` TEXT COLLATE NOCASE CONSTRAINT `ck_len_decided_by` CHECK (length(`decided_by`) <= 36),
  `basis` TEXT COLLATE NOCASE NOT NULL CHECK (basis IN('HUMAN','AUTO_POLICY','REGISTRY')) CONSTRAINT `ck_len_basis` CHECK (length(`basis`) <= 255),
  `evidence_id` TEXT COLLATE NOCASE CONSTRAINT `ck_len_evidence_id` CHECK (length(`evidence_id`) <= 36),
  `decided_at` INTEGER NOT NULL DEFAULT (CAST(unixepoch('subsec')*1000 AS INTEGER)),
  `supersedes_id` TEXT COLLATE NOCASE CONSTRAINT `ck_len_supersedes_id` CHECK (length(`supersedes_id`) <= 36),
  CHECK (state <> 'CONFIRMED' OR player_id IS NOT NULL),
  CHECK (basis <> 'HUMAN' OR decided_by IS NOT NULL)
) STRICT;
CREATE TABLE `pitch_calibrations` (
  `id` TEXT COLLATE NOCASE PRIMARY KEY CONSTRAINT `ck_len_id` CHECK (length(`id`) <= 36),
  `video_id` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_len_video_id` CHECK (length(`video_id`) <= 36),
  `shot_id` TEXT COLLATE NOCASE CONSTRAINT `ck_len_shot_id` CHECK (length(`shot_id`) <= 36),
  `start_pts_us` INTEGER NOT NULL,
  `end_pts_us` INTEGER NOT NULL,
  `transform_matrix` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_json_transform_matrix` CHECK (json_valid(`transform_matrix`)),
  `pitch_length_m` REAL,
  `pitch_width_m` REAL,
  `reprojection_error_px` REAL,
  `evidence_state` TEXT COLLATE NOCASE NOT NULL DEFAULT 'INFERRED' CONSTRAINT `ck_enum_evidence_state` CHECK (`evidence_state` IN ('DETECTED', 'INFERRED', 'CONFIRMED', 'NOT_MEASURED')),
  `quality_score` REAL CHECK (quality_score BETWEEN 0 AND 1),
  `model_version_id` TEXT COLLATE NOCASE CONSTRAINT `ck_len_model_version_id` CHECK (length(`model_version_id`) <= 36),
  CHECK (end_pts_us>start_pts_us)
) STRICT;
CREATE TABLE `event_candidates` (
  `id` TEXT COLLATE NOCASE PRIMARY KEY CONSTRAINT `ck_len_id` CHECK (length(`id`) <= 36),
  `run_id` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_len_run_id` CHECK (length(`run_id`) <= 36),
  `video_id` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_len_video_id` CHECK (length(`video_id`) <= 36),
  `event_type` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_len_event_type` CHECK (length(`event_type`) <= 255),
  `start_pts_us` INTEGER NOT NULL,
  `end_pts_us` INTEGER NOT NULL,
  `primary_track_id` TEXT COLLATE NOCASE CONSTRAINT `ck_len_primary_track_id` CHECK (length(`primary_track_id`) <= 36),
  `secondary_track_id` TEXT COLLATE NOCASE CONSTRAINT `ck_len_secondary_track_id` CHECK (length(`secondary_track_id`) <= 36),
  `confidence` REAL CHECK (confidence BETWEEN 0 AND 1),
  `evidence_state` TEXT COLLATE NOCASE NOT NULL DEFAULT 'DETECTED' CONSTRAINT `ck_enum_evidence_state` CHECK (`evidence_state` IN ('DETECTED', 'INFERRED', 'CONFIRMED', 'NOT_MEASURED')),
  `model_version_id` TEXT COLLATE NOCASE CONSTRAINT `ck_len_model_version_id` CHECK (length(`model_version_id`) <= 36),
  `evidence_id` TEXT COLLATE NOCASE CONSTRAINT `ck_len_evidence_id` CHECK (length(`evidence_id`) <= 36),
  `features` TEXT COLLATE NOCASE NOT NULL DEFAULT (json_object()) CONSTRAINT `ck_json_features` CHECK (json_valid(`features`)),
  CHECK (end_pts_us>=start_pts_us)
) STRICT;
CREATE TABLE `event_decisions` (
  `id` TEXT COLLATE NOCASE PRIMARY KEY CONSTRAINT `ck_len_id` CHECK (length(`id`) <= 36),
  `event_id` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_len_event_id` CHECK (length(`event_id`) <= 36),
  `decision` TEXT COLLATE NOCASE NOT NULL CHECK (decision IN('CONFIRM','REJECT','EDIT','NEEDS_REVIEW')) CONSTRAINT `ck_len_decision` CHECK (length(`decision`) <= 255),
  `reviewer_id` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_len_reviewer_id` CHECK (length(`reviewer_id`) <= 36),
  `revised_start_pts_us` INTEGER,
  `revised_end_pts_us` INTEGER,
  `revised_type` TEXT COLLATE NOCASE CONSTRAINT `ck_len_revised_type` CHECK (length(`revised_type`) <= 255),
  `reason` TEXT COLLATE NOCASE,
  `decided_at` INTEGER NOT NULL DEFAULT (CAST(unixepoch('subsec')*1000 AS INTEGER))
) STRICT;
CREATE TABLE `metric_definitions` (
  `key` TEXT COLLATE NOCASE PRIMARY KEY CONSTRAINT `ck_len_key` CHECK (length(`key`) <= 255),
  `unit` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_len_unit` CHECK (length(`unit`) <= 255),
  `formula_version` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_len_formula_version` CHECK (length(`formula_version`) <= 255),
  `minimum_quality` REAL NOT NULL DEFAULT 0 CHECK (minimum_quality BETWEEN 0 AND 1),
  `measurement_class` TEXT COLLATE NOCASE NOT NULL CHECK (measurement_class IN('PIXEL','PITCH_CALIBRATED','OBSERVED_EVENT','MODEL_ESTIMATE','HUMAN_REVIEW')) CONSTRAINT `ck_len_measurement_class` CHECK (length(`measurement_class`) <= 255)
) STRICT;
CREATE TABLE `metric_values` (
  `id` TEXT COLLATE NOCASE PRIMARY KEY CONSTRAINT `ck_len_id` CHECK (length(`id`) <= 36),
  `video_id` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_len_video_id` CHECK (length(`video_id`) <= 36),
  `player_id` TEXT COLLATE NOCASE CONSTRAINT `ck_len_player_id` CHECK (length(`player_id`) <= 36),
  `track_id` TEXT COLLATE NOCASE CONSTRAINT `ck_len_track_id` CHECK (length(`track_id`) <= 36),
  `metric_key` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_len_metric_key` CHECK (length(`metric_key`) <= 255),
  `value_numeric` REAL,
  `evidence_state` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_enum_evidence_state` CHECK (`evidence_state` IN ('DETECTED', 'INFERRED', 'CONFIRMED', 'NOT_MEASURED')),
  `evidence_id` TEXT COLLATE NOCASE CONSTRAINT `ck_len_evidence_id` CHECK (length(`evidence_id`) <= 36),
  `quality_score` REAL CHECK (quality_score BETWEEN 0 AND 1),
  `start_pts_us` INTEGER NOT NULL,
  `end_pts_us` INTEGER NOT NULL,
  `computed_at` INTEGER NOT NULL DEFAULT (CAST(unixepoch('subsec')*1000 AS INTEGER)),
  `model_version_id` TEXT COLLATE NOCASE CONSTRAINT `ck_len_model_version_id` CHECK (length(`model_version_id`) <= 36),
  CHECK (end_pts_us>=start_pts_us),
  CHECK (evidence_state <> 'NOT_MEASURED' OR value_numeric IS NULL)
) STRICT;
CREATE TABLE `reel_projects` (
  `id` TEXT COLLATE NOCASE PRIMARY KEY CONSTRAINT `ck_len_id` CHECK (length(`id`) <= 36),
  `organization_id` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_len_organization_id` CHECK (length(`organization_id`) <= 36),
  `project_id` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_len_project_id` CHECK (length(`project_id`) <= 36),
  `video_id` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_len_video_id` CHECK (length(`video_id`) <= 36),
  `name` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_len_name` CHECK (length(`name`) <= 255),
  `created_by` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_len_created_by` CHECK (length(`created_by`) <= 36),
  `status` TEXT COLLATE NOCASE NOT NULL DEFAULT 'DRAFT' CHECK (status IN('DRAFT','READY','RENDERING','PUBLISHED','BLOCKED','ARCHIVED')) CONSTRAINT `ck_len_status` CHECK (length(`status`) <= 255),
  `version` INTEGER NOT NULL DEFAULT 1,
  `created_at` INTEGER NOT NULL DEFAULT (CAST(unixepoch('subsec')*1000 AS INTEGER)),
  `updated_at` INTEGER NOT NULL DEFAULT (CAST(unixepoch('subsec')*1000 AS INTEGER))
) STRICT;
CREATE TABLE `reel_targets` (
  `reel_id` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_len_reel_id` CHECK (length(`reel_id`) <= 36),
  `track_id` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_len_track_id` CHECK (length(`track_id`) <= 36),
  `player_id` TEXT COLLATE NOCASE CONSTRAINT `ck_len_player_id` CHECK (length(`player_id`) <= 36),
  `identity_decision_id` TEXT COLLATE NOCASE CONSTRAINT `ck_len_identity_decision_id` CHECK (length(`identity_decision_id`) <= 36),
  PRIMARY KEY (`reel_id`, `track_id`)
) STRICT;
CREATE TABLE `reel_clips` (
  `id` TEXT COLLATE NOCASE PRIMARY KEY CONSTRAINT `ck_len_id` CHECK (length(`id`) <= 36),
  `reel_id` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_len_reel_id` CHECK (length(`reel_id`) <= 36),
  `source_video_id` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_len_source_video_id` CHECK (length(`source_video_id`) <= 36),
  `in_pts_us` INTEGER NOT NULL CHECK (in_pts_us>=0),
  `out_pts_us` INTEGER NOT NULL,
  `sequence_index` INTEGER NOT NULL CHECK (sequence_index>=0),
  `output_duration_us` INTEGER,
  `playback_speed` REAL NOT NULL DEFAULT 1 CHECK (playback_speed>0),
  `source_event_id` TEXT COLLATE NOCASE CONSTRAINT `ck_len_source_event_id` CHECK (length(`source_event_id`) <= 36),
  `review_state` TEXT COLLATE NOCASE NOT NULL DEFAULT 'PENDING' CHECK (review_state IN('PENDING','APPROVED','REJECTED','RED')) CONSTRAINT `ck_len_review_state` CHECK (length(`review_state`) <= 255),
  UNIQUE (`reel_id`, `sequence_index`),
  CHECK (out_pts_us>in_pts_us)
) STRICT;
CREATE TABLE `effect_presets` (
  `id` TEXT COLLATE NOCASE PRIMARY KEY CONSTRAINT `ck_len_id` CHECK (length(`id`) <= 36),
  `organization_id` TEXT COLLATE NOCASE CONSTRAINT `ck_len_organization_id` CHECK (length(`organization_id`) <= 36),
  `name` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_len_name` CHECK (length(`name`) <= 255),
  `version` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_len_version` CHECK (length(`version`) <= 255),
  `schema_version` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_len_schema_version` CHECK (length(`schema_version`) <= 255),
  `config` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_json_config` CHECK (json_valid(`config`)),
  `created_at` INTEGER NOT NULL DEFAULT (CAST(unixepoch('subsec')*1000 AS INTEGER)),
  UNIQUE (`organization_id`, `name`, `version`)
) STRICT;
CREATE TABLE `timeline_tracks` (
  `id` TEXT COLLATE NOCASE PRIMARY KEY CONSTRAINT `ck_len_id` CHECK (length(`id`) <= 36),
  `reel_id` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_len_reel_id` CHECK (length(`reel_id`) <= 36),
  `track_type` TEXT COLLATE NOCASE NOT NULL CHECK (track_type IN('VIDEO','SPOTLIGHT','GRAPHICS','CAPTIONS','STATISTICS','AUDIO','TRANSITION')) CONSTRAINT `ck_len_track_type` CHECK (length(`track_type`) <= 255),
  `layer` INTEGER NOT NULL,
  `muted` INTEGER NOT NULL DEFAULT 0,
  `locked` INTEGER NOT NULL DEFAULT 0,
  UNIQUE (`reel_id`, `track_type`, `layer`)
) STRICT;
CREATE TABLE `timeline_items` (
  `id` TEXT COLLATE NOCASE PRIMARY KEY CONSTRAINT `ck_len_id` CHECK (length(`id`) <= 36),
  `timeline_track_id` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_len_timeline_track_id` CHECK (length(`timeline_track_id`) <= 36),
  `reel_clip_id` TEXT COLLATE NOCASE CONSTRAINT `ck_len_reel_clip_id` CHECK (length(`reel_clip_id`) <= 36),
  `start_us` INTEGER NOT NULL CHECK (start_us>=0),
  `duration_us` INTEGER NOT NULL CHECK (duration_us>0),
  `effect_preset_id` TEXT COLLATE NOCASE CONSTRAINT `ck_len_effect_preset_id` CHECK (length(`effect_preset_id`) <= 36),
  `parameters` TEXT COLLATE NOCASE NOT NULL DEFAULT (json_object()) CONSTRAINT `ck_json_parameters` CHECK (json_valid(`parameters`)),
  `asset_id` TEXT COLLATE NOCASE CONSTRAINT `ck_len_asset_id` CHECK (length(`asset_id`) <= 36)
) STRICT;
CREATE TABLE `effect_keyframes` (
  `id` TEXT COLLATE NOCASE PRIMARY KEY CONSTRAINT `ck_len_id` CHECK (length(`id`) <= 36),
  `timeline_item_id` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_len_timeline_item_id` CHECK (length(`timeline_item_id`) <= 36),
  `time_offset_us` INTEGER NOT NULL CHECK (time_offset_us>=0),
  `property_name` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_len_property_name` CHECK (length(`property_name`) <= 255),
  `value` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_json_value` CHECK (json_valid(`value`)),
  `interpolation` TEXT COLLATE NOCASE NOT NULL DEFAULT 'LINEAR' CHECK (interpolation IN('HOLD','LINEAR','EASE_IN_OUT')) CONSTRAINT `ck_len_interpolation` CHECK (length(`interpolation`) <= 255),
  UNIQUE (`timeline_item_id`, `time_offset_us`, `property_name`)
) STRICT;
CREATE TABLE `render_jobs` (
  `id` TEXT COLLATE NOCASE PRIMARY KEY CONSTRAINT `ck_len_id` CHECK (length(`id`) <= 36),
  `reel_id` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_len_reel_id` CHECK (length(`reel_id`) <= 36),
  `organization_id` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_len_organization_id` CHECK (length(`organization_id`) <= 36),
  `requested_by` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_len_requested_by` CHECK (length(`requested_by`) <= 36),
  `state` TEXT COLLATE NOCASE NOT NULL DEFAULT 'QUEUED' CONSTRAINT `ck_enum_state` CHECK (`state` IN ('QUEUED', 'RUNNING', 'SUCCEEDED', 'FAILED', 'CANCELLED', 'BLOCKED', 'REVIEW_REQUIRED')),
  `config` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_json_config` CHECK (json_valid(`config`)),
  `manifest_asset_id` TEXT COLLATE NOCASE CONSTRAINT `ck_len_manifest_asset_id` CHECK (length(`manifest_asset_id`) <= 36),
  `output_asset_id` TEXT COLLATE NOCASE CONSTRAINT `ck_len_output_asset_id` CHECK (length(`output_asset_id`) <= 36),
  `idempotency_key` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_len_idempotency_key` CHECK (length(`idempotency_key`) <= 255),
  `attempt_count` INTEGER NOT NULL DEFAULT 0,
  `failure_code` TEXT COLLATE NOCASE CONSTRAINT `ck_len_failure_code` CHECK (length(`failure_code`) <= 255),
  `created_at` INTEGER NOT NULL DEFAULT (CAST(unixepoch('subsec')*1000 AS INTEGER)),
  `started_at` INTEGER,
  `completed_at` INTEGER,
  UNIQUE (`organization_id`, `idempotency_key`)
) STRICT;
CREATE TABLE `report_jobs` (
  `id` TEXT COLLATE NOCASE PRIMARY KEY CONSTRAINT `ck_len_id` CHECK (length(`id`) <= 36),
  `organization_id` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_len_organization_id` CHECK (length(`organization_id`) <= 36),
  `project_id` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_len_project_id` CHECK (length(`project_id`) <= 36),
  `video_id` TEXT COLLATE NOCASE CONSTRAINT `ck_len_video_id` CHECK (length(`video_id`) <= 36),
  `player_id` TEXT COLLATE NOCASE CONSTRAINT `ck_len_player_id` CHECK (length(`player_id`) <= 36),
  `requested_by` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_len_requested_by` CHECK (length(`requested_by`) <= 36),
  `state` TEXT COLLATE NOCASE NOT NULL DEFAULT 'QUEUED' CONSTRAINT `ck_enum_state` CHECK (`state` IN ('QUEUED', 'RUNNING', 'SUCCEEDED', 'FAILED', 'CANCELLED', 'BLOCKED', 'REVIEW_REQUIRED')),
  `report_type` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_len_report_type` CHECK (length(`report_type`) <= 255),
  `config` TEXT COLLATE NOCASE NOT NULL DEFAULT (json_object()) CONSTRAINT `ck_json_config` CHECK (json_valid(`config`)),
  `output_asset_id` TEXT COLLATE NOCASE CONSTRAINT `ck_len_output_asset_id` CHECK (length(`output_asset_id`) <= 36),
  `created_at` INTEGER NOT NULL DEFAULT (CAST(unixepoch('subsec')*1000 AS INTEGER))
) STRICT;
CREATE TABLE `share_links` (
  `id` TEXT COLLATE NOCASE PRIMARY KEY CONSTRAINT `ck_len_id` CHECK (length(`id`) <= 36),
  `organization_id` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_len_organization_id` CHECK (length(`organization_id`) <= 36),
  `asset_id` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_len_asset_id` CHECK (length(`asset_id`) <= 36),
  `created_by` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_len_created_by` CHECK (length(`created_by`) <= 36),
  `token_hash` TEXT COLLATE NOCASE NOT NULL UNIQUE CONSTRAINT `ck_len_token_hash` CHECK (length(`token_hash`) <= 64),
  `expires_at` INTEGER,
  `can_download` INTEGER NOT NULL DEFAULT 0,
  `can_comment` INTEGER NOT NULL DEFAULT 0,
  `revoked_at` INTEGER,
  `password_hash` TEXT COLLATE NOCASE CONSTRAINT `ck_len_password_hash` CHECK (length(`password_hash`) <= 255),
  `created_at` INTEGER NOT NULL DEFAULT (CAST(unixepoch('subsec')*1000 AS INTEGER))
) STRICT;
CREATE TABLE `deliveries` (
  `id` TEXT COLLATE NOCASE PRIMARY KEY CONSTRAINT `ck_len_id` CHECK (length(`id`) <= 36),
  `organization_id` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_len_organization_id` CHECK (length(`organization_id`) <= 36),
  `asset_id` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_len_asset_id` CHECK (length(`asset_id`) <= 36),
  `requested_by` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_len_requested_by` CHECK (length(`requested_by`) <= 36),
  `destination_type` TEXT COLLATE NOCASE NOT NULL CHECK (destination_type IN('SIGNED_URL','EMAIL_INVITE','INTERNAL')) CONSTRAINT `ck_len_destination_type` CHECK (length(`destination_type`) <= 255),
  `destination_ref` TEXT COLLATE NOCASE CONSTRAINT `ck_len_destination_ref` CHECK (length(`destination_ref`) <= 255),
  `state` TEXT COLLATE NOCASE NOT NULL DEFAULT 'QUEUED' CONSTRAINT `ck_enum_state` CHECK (`state` IN ('QUEUED', 'RUNNING', 'SUCCEEDED', 'FAILED', 'CANCELLED', 'BLOCKED', 'REVIEW_REQUIRED')),
  `rights_checked_at` INTEGER,
  `delivered_at` INTEGER,
  `failure_code` TEXT COLLATE NOCASE CONSTRAINT `ck_len_failure_code` CHECK (length(`failure_code`) <= 255)
) STRICT;
CREATE TABLE `comments` (
  `id` TEXT COLLATE NOCASE PRIMARY KEY CONSTRAINT `ck_len_id` CHECK (length(`id`) <= 36),
  `organization_id` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_len_organization_id` CHECK (length(`organization_id`) <= 36),
  `project_id` TEXT COLLATE NOCASE CONSTRAINT `ck_len_project_id` CHECK (length(`project_id`) <= 36),
  `reel_id` TEXT COLLATE NOCASE CONSTRAINT `ck_len_reel_id` CHECK (length(`reel_id`) <= 36),
  `author_id` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_len_author_id` CHECK (length(`author_id`) <= 36),
  `body` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_len_body` CHECK (length(`body`) <= 255),
  `at_pts_us` INTEGER,
  `created_at` INTEGER NOT NULL DEFAULT (CAST(unixepoch('subsec')*1000 AS INTEGER))
) STRICT;
CREATE TABLE `outbox_events` (
  `id` INTEGER PRIMARY KEY AUTOINCREMENT,
  `aggregate_type` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_len_aggregate_type` CHECK (length(`aggregate_type`) <= 255),
  `aggregate_id` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_len_aggregate_id` CHECK (length(`aggregate_id`) <= 36),
  `event_type` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_len_event_type` CHECK (length(`event_type`) <= 255),
  `event_payload` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_json_event_payload` CHECK (json_valid(`event_payload`)),
  `created_at` INTEGER NOT NULL DEFAULT (CAST(unixepoch('subsec')*1000 AS INTEGER)),
  `claimed_at` INTEGER,
  `delivered_at` INTEGER,
  `attempt_count` INTEGER NOT NULL DEFAULT 0
) STRICT;
CREATE TABLE `upload_sessions` (
  `id` TEXT COLLATE NOCASE PRIMARY KEY CONSTRAINT `ck_len_id` CHECK (length(`id`) <= 36),
  `organization_id` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_len_organization_id` CHECK (length(`organization_id`) <= 36),
  `video_id` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_len_video_id` CHECK (length(`video_id`) <= 36),
  `created_by` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_len_created_by` CHECK (length(`created_by`) <= 36),
  `idempotency_key` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_len_idempotency_key` CHECK (length(`idempotency_key`) <= 255),
  `multipart_upload_id` TEXT COLLATE NOCASE CONSTRAINT `ck_len_multipart_upload_id` CHECK (length(`multipart_upload_id`) <= 255),
  `expected_bytes` INTEGER NOT NULL CHECK (expected_bytes>0),
  `expected_sha256` TEXT COLLATE NOCASE CONSTRAINT `ck_len_expected_sha256` CHECK (length(`expected_sha256`) <= 64),
  `transferred_bytes` INTEGER NOT NULL DEFAULT 0 CHECK (transferred_bytes>=0),
  `status` TEXT COLLATE NOCASE NOT NULL DEFAULT 'INITIALIZED' CHECK (status IN('INITIALIZED','UPLOADING','VERIFYING','COMPLETED','ABORTED','EXPIRED','FAILED')) CONSTRAINT `ck_len_status` CHECK (length(`status`) <= 255),
  `expires_at` INTEGER NOT NULL,
  `created_at` INTEGER NOT NULL DEFAULT (CAST(unixepoch('subsec')*1000 AS INTEGER)),
  UNIQUE (`organization_id`, `idempotency_key`)
) STRICT;
CREATE TABLE `upload_parts` (
  `session_id` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_len_session_id` CHECK (length(`session_id`) <= 36),
  `part_number` INTEGER NOT NULL CHECK (part_number>0),
  `byte_size` INTEGER NOT NULL CHECK (byte_size>0),
  `remote_etag` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_len_remote_etag` CHECK (length(`remote_etag`) <= 255),
  `checked_at` INTEGER,
  PRIMARY KEY (`session_id`, `part_number`)
) STRICT;
CREATE TABLE `project_acl` (
  `project_id` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_len_project_id` CHECK (length(`project_id`) <= 36),
  `user_id` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_len_user_id` CHECK (length(`user_id`) <= 36),
  `permission` TEXT COLLATE NOCASE NOT NULL CHECK (permission IN ('READ','EDIT','REVIEW','ADMIN')) CONSTRAINT `ck_len_permission` CHECK (length(`permission`) <= 255),
  `granted_by` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_len_granted_by` CHECK (length(`granted_by`) <= 36),
  `granted_at` INTEGER NOT NULL DEFAULT (CAST(unixepoch('subsec')*1000 AS INTEGER)),
  PRIMARY KEY (`project_id`, `user_id`, `permission`)
) STRICT;
CREATE TABLE `metric_cohorts` (
  `id` TEXT COLLATE NOCASE PRIMARY KEY CONSTRAINT `ck_len_id` CHECK (length(`id`) <= 36),
  `organization_id` TEXT COLLATE NOCASE CONSTRAINT `ck_len_organization_id` CHECK (length(`organization_id`) <= 36),
  `name` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_len_name` CHECK (length(`name`) <= 255),
  `version` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_len_version` CHECK (length(`version`) <= 255),
  `definition` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_json_definition` CHECK (json_valid(`definition`)),
  `sample_count` INTEGER CHECK (sample_count>=0),
  `created_at` INTEGER NOT NULL DEFAULT (CAST(unixepoch('subsec')*1000 AS INTEGER))
) STRICT;
CREATE TABLE `saved_searches` (
  `id` TEXT COLLATE NOCASE PRIMARY KEY CONSTRAINT `ck_len_id` CHECK (length(`id`) <= 36),
  `organization_id` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_len_organization_id` CHECK (length(`organization_id`) <= 36),
  `user_id` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_len_user_id` CHECK (length(`user_id`) <= 36),
  `name` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_len_name` CHECK (length(`name`) <= 255),
  `query` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_json_query` CHECK (json_valid(`query`)),
  `created_at` INTEGER NOT NULL DEFAULT (CAST(unixepoch('subsec')*1000 AS INTEGER)),
  UNIQUE (`organization_id`, `user_id`, `name`)
) STRICT;
CREATE TABLE `clip_reviews` (
  `id` TEXT COLLATE NOCASE PRIMARY KEY CONSTRAINT `ck_len_id` CHECK (length(`id`) <= 36),
  `reel_clip_id` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_len_reel_clip_id` CHECK (length(`reel_clip_id`) <= 36),
  `reviewer_id` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_len_reviewer_id` CHECK (length(`reviewer_id`) <= 36),
  `decision` TEXT COLLATE NOCASE NOT NULL CHECK (decision IN('APPROVED','REJECTED','RED','NEEDS_REVIEW')) CONSTRAINT `ck_len_decision` CHECK (length(`decision`) <= 255),
  `evidence_id` TEXT COLLATE NOCASE CONSTRAINT `ck_len_evidence_id` CHECK (length(`evidence_id`) <= 36),
  `reason` TEXT COLLATE NOCASE,
  `created_at` INTEGER NOT NULL DEFAULT (CAST(unixepoch('subsec')*1000 AS INTEGER))
) STRICT;
CREATE TABLE `policy_decisions` (
  `id` TEXT COLLATE NOCASE PRIMARY KEY CONSTRAINT `ck_len_id` CHECK (length(`id`) <= 36),
  `organization_id` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_len_organization_id` CHECK (length(`organization_id`) <= 36),
  `action` TEXT COLLATE NOCASE NOT NULL CHECK (action IN('ANALYZE','PRODUCE','EXPORT','VIEW','DOWNLOAD','SHARE','DELIVER')) CONSTRAINT `ck_len_action` CHECK (length(`action`) <= 255),
  `resource_type` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_len_resource_type` CHECK (length(`resource_type`) <= 255),
  `resource_id` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_len_resource_id` CHECK (length(`resource_id`) <= 36),
  `actor_id` TEXT COLLATE NOCASE CONSTRAINT `ck_len_actor_id` CHECK (length(`actor_id`) <= 36),
  `decision` TEXT COLLATE NOCASE NOT NULL CHECK (decision IN('ALLOW','DENY','REVIEW')) CONSTRAINT `ck_len_decision` CHECK (length(`decision`) <= 255),
  `rule_version` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_len_rule_version` CHECK (length(`rule_version`) <= 255),
  `grant_ids` TEXT COLLATE NOCASE NOT NULL DEFAULT (json_array()) CONSTRAINT `ck_json_grant_ids` CHECK (json_valid(`grant_ids`)),
  `dependency_asset_ids` TEXT COLLATE NOCASE NOT NULL DEFAULT (json_array()) CONSTRAINT `ck_json_dependency_asset_ids` CHECK (json_valid(`dependency_asset_ids`)),
  `reason_codes` TEXT COLLATE NOCASE NOT NULL DEFAULT (json_array()) CONSTRAINT `ck_json_reason_codes` CHECK (json_valid(`reason_codes`)),
  `checked_at` INTEGER NOT NULL DEFAULT (CAST(unixepoch('subsec')*1000 AS INTEGER))
) STRICT;
CREATE TABLE `artifact_dependencies` (
  `artifact_asset_id` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_len_artifact_asset_id` CHECK (length(`artifact_asset_id`) <= 36),
  `depends_on_asset_id` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_len_depends_on_asset_id` CHECK (length(`depends_on_asset_id`) <= 36),
  `dependency_type` TEXT COLLATE NOCASE NOT NULL CHECK (dependency_type IN('SOURCE_VIDEO','AUDIO','FONT','LOGO','TRACKS','MODEL','METADATA','OTHER')) CONSTRAINT `ck_len_dependency_type` CHECK (length(`dependency_type`) <= 255),
  PRIMARY KEY (`artifact_asset_id`, `depends_on_asset_id`, `dependency_type`),
  CHECK (artifact_asset_id<>depends_on_asset_id)
) STRICT;
CREATE TABLE `share_link_access` (
  `id` INTEGER PRIMARY KEY AUTOINCREMENT,
  `share_link_id` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_len_share_link_id` CHECK (length(`share_link_id`) <= 36),
  `actor_id` TEXT COLLATE NOCASE CONSTRAINT `ck_len_actor_id` CHECK (length(`actor_id`) <= 36),
  `action` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_len_action` CHECK (length(`action`) <= 255),
  `decision` TEXT COLLATE NOCASE NOT NULL CHECK (decision IN('ALLOW','DENY')) CONSTRAINT `ck_len_decision` CHECK (length(`decision`) <= 255),
  `accessed_at` INTEGER NOT NULL DEFAULT (CAST(unixepoch('subsec')*1000 AS INTEGER)),
  `ip_hash` TEXT COLLATE NOCASE CONSTRAINT `ck_len_ip_hash` CHECK (length(`ip_hash`) <= 64)
) STRICT;
CREATE TABLE `model_evaluations` (
  `id` TEXT COLLATE NOCASE PRIMARY KEY CONSTRAINT `ck_len_id` CHECK (length(`id`) <= 36),
  `model_version_id` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_len_model_version_id` CHECK (length(`model_version_id`) <= 36),
  `dataset_name` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_len_dataset_name` CHECK (length(`dataset_name`) <= 255),
  `dataset_sha256` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_len_dataset_sha256` CHECK (length(`dataset_sha256`) <= 64),
  `annotation_version` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_len_annotation_version` CHECK (length(`annotation_version`) <= 255),
  `metrics` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_json_metrics` CHECK (json_valid(`metrics`)),
  `signed_off_by` TEXT COLLATE NOCASE CONSTRAINT `ck_len_signed_off_by` CHECK (length(`signed_off_by`) <= 36),
  `created_at` INTEGER NOT NULL DEFAULT (CAST(unixepoch('subsec')*1000 AS INTEGER))
) STRICT;
CREATE TABLE `plans` (
  `id` TEXT COLLATE NOCASE PRIMARY KEY CONSTRAINT `ck_len_id` CHECK (length(`id`) <= 36),
  `code` TEXT COLLATE NOCASE NOT NULL UNIQUE CONSTRAINT `ck_len_code` CHECK (length(`code`) <= 255),
  `name` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_len_name` CHECK (length(`name`) <= 255),
  `active` INTEGER NOT NULL DEFAULT 1,
  `created_at` INTEGER NOT NULL DEFAULT (CAST(unixepoch('subsec')*1000 AS INTEGER))
) STRICT;
CREATE TABLE `plan_versions` (
  `id` TEXT COLLATE NOCASE PRIMARY KEY CONSTRAINT `ck_len_id` CHECK (length(`id`) <= 36),
  `plan_id` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_len_plan_id` CHECK (length(`plan_id`) <= 36),
  `version` INTEGER NOT NULL CHECK (version>0),
  `effective_at` INTEGER NOT NULL DEFAULT (CAST(unixepoch('subsec')*1000 AS INTEGER)),
  `feature_limits` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_json_feature_limits` CHECK (json_valid(`feature_limits`)),
  `currency` TEXT COLLATE NOCASE CONSTRAINT `ck_len_currency` CHECK (length(`currency`) <= 255),
  `is_published` INTEGER NOT NULL DEFAULT 0,
  UNIQUE (`plan_id`, `version`)
) STRICT;
CREATE TABLE `plan_prices` (
  `id` TEXT COLLATE NOCASE PRIMARY KEY CONSTRAINT `ck_len_id` CHECK (length(`id`) <= 36),
  `plan_version_id` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_len_plan_version_id` CHECK (length(`plan_version_id`) <= 36),
  `provider` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_len_provider` CHECK (length(`provider`) <= 255),
  `external_price_id` TEXT COLLATE NOCASE NOT NULL UNIQUE CONSTRAINT `ck_len_external_price_id` CHECK (length(`external_price_id`) <= 255),
  `billing_period` TEXT COLLATE NOCASE NOT NULL CHECK (billing_period IN('MONTHLY','YEARLY','CUSTOM')) CONSTRAINT `ck_len_billing_period` CHECK (length(`billing_period`) <= 255),
  `currency` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_len_currency` CHECK (length(`currency`) <= 3),
  `unit_amount_minor` INTEGER NOT NULL CHECK (unit_amount_minor>=0),
  `created_at` INTEGER NOT NULL DEFAULT (CAST(unixepoch('subsec')*1000 AS INTEGER))
) STRICT;
CREATE TABLE `billing_customers` (
  `id` TEXT COLLATE NOCASE PRIMARY KEY CONSTRAINT `ck_len_id` CHECK (length(`id`) <= 36),
  `organization_id` TEXT COLLATE NOCASE NOT NULL UNIQUE CONSTRAINT `ck_len_organization_id` CHECK (length(`organization_id`) <= 36),
  `provider` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_len_provider` CHECK (length(`provider`) <= 255),
  `provider_customer_id` TEXT COLLATE NOCASE NOT NULL UNIQUE CONSTRAINT `ck_len_provider_customer_id` CHECK (length(`provider_customer_id`) <= 255),
  `created_at` INTEGER NOT NULL DEFAULT (CAST(unixepoch('subsec')*1000 AS INTEGER))
) STRICT;
CREATE TABLE `subscriptions` (
  `id` TEXT COLLATE NOCASE PRIMARY KEY CONSTRAINT `ck_len_id` CHECK (length(`id`) <= 36),
  `organization_id` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_len_organization_id` CHECK (length(`organization_id`) <= 36),
  `plan_version_id` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_len_plan_version_id` CHECK (length(`plan_version_id`) <= 36),
  `provider_subscription_id` TEXT COLLATE NOCASE UNIQUE CONSTRAINT `ck_len_provider_subscription_id` CHECK (length(`provider_subscription_id`) <= 255),
  `state` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_enum_state` CHECK (`state` IN ('TRIALING', 'ACTIVE', 'PAST_DUE', 'CANCELED', 'UNPAID', 'INCOMPLETE')),
  `period_start` INTEGER,
  `period_end` INTEGER,
  `trial_end` INTEGER,
  `cancel_at_period_end` INTEGER NOT NULL DEFAULT 0,
  `version` INTEGER NOT NULL DEFAULT 1,
  `created_at` INTEGER NOT NULL DEFAULT (CAST(unixepoch('subsec')*1000 AS INTEGER)),
  CHECK (period_end IS NULL OR period_start IS NULL OR period_end>period_start)
) STRICT;
CREATE TABLE `billing_webhook_inbox` (
  `id` INTEGER PRIMARY KEY AUTOINCREMENT,
  `provider` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_len_provider` CHECK (length(`provider`) <= 255),
  `external_event_id` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_len_external_event_id` CHECK (length(`external_event_id`) <= 255),
  `signature_verified` INTEGER NOT NULL DEFAULT 0,
  `event_kind` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_len_event_kind` CHECK (length(`event_kind`) <= 255),
  `payload_sha256` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_len_payload_sha256` CHECK (length(`payload_sha256`) <= 64),
  `received_at` INTEGER NOT NULL DEFAULT (CAST(unixepoch('subsec')*1000 AS INTEGER)),
  `processed_at` INTEGER,
  `error_code` TEXT COLLATE NOCASE CONSTRAINT `ck_len_error_code` CHECK (length(`error_code`) <= 255),
  UNIQUE (`provider`, `external_event_id`)
) STRICT;
CREATE TABLE `invoices` (
  `id` TEXT COLLATE NOCASE PRIMARY KEY CONSTRAINT `ck_len_id` CHECK (length(`id`) <= 36),
  `organization_id` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_len_organization_id` CHECK (length(`organization_id`) <= 36),
  `provider_invoice_id` TEXT COLLATE NOCASE UNIQUE CONSTRAINT `ck_len_provider_invoice_id` CHECK (length(`provider_invoice_id`) <= 255),
  `subscription_id` TEXT COLLATE NOCASE CONSTRAINT `ck_len_subscription_id` CHECK (length(`subscription_id`) <= 36),
  `amount_due_minor` INTEGER NOT NULL CHECK (amount_due_minor>=0),
  `currency` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_len_currency` CHECK (length(`currency`) <= 3),
  `invoice_state` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_len_invoice_state` CHECK (length(`invoice_state`) <= 255),
  `occurred_at` INTEGER NOT NULL DEFAULT (CAST(unixepoch('subsec')*1000 AS INTEGER))
) STRICT;
CREATE TABLE `entitlement_grants` (
  `id` TEXT COLLATE NOCASE PRIMARY KEY CONSTRAINT `ck_len_id` CHECK (length(`id`) <= 36),
  `organization_id` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_len_organization_id` CHECK (length(`organization_id`) <= 36),
  `source_subscription_id` TEXT COLLATE NOCASE CONSTRAINT `ck_len_source_subscription_id` CHECK (length(`source_subscription_id`) <= 36),
  `feature_key` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_len_feature_key` CHECK (length(`feature_key`) <= 255),
  `limit_value` INTEGER,
  `valid_from` INTEGER NOT NULL,
  `valid_until` INTEGER,
  CHECK (valid_until IS NULL OR valid_until>valid_from)
) STRICT;
CREATE TABLE `quota_counters` (
  `organization_id` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_len_organization_id` CHECK (length(`organization_id`) <= 36),
  `feature_key` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_len_feature_key` CHECK (length(`feature_key`) <= 255),
  `window_start` INTEGER NOT NULL,
  `used_amount` INTEGER NOT NULL DEFAULT 0 CHECK (used_amount>=0),
  `reserved_amount` INTEGER NOT NULL DEFAULT 0 CHECK (reserved_amount>=0),
  PRIMARY KEY (`organization_id`, `feature_key`, `window_start`)
) STRICT;
CREATE TABLE `quota_reservations` (
  `id` TEXT COLLATE NOCASE PRIMARY KEY CONSTRAINT `ck_len_id` CHECK (length(`id`) <= 36),
  `organization_id` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_len_organization_id` CHECK (length(`organization_id`) <= 36),
  `feature_key` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_len_feature_key` CHECK (length(`feature_key`) <= 255),
  `window_start` INTEGER NOT NULL,
  `quantity` INTEGER NOT NULL CHECK (quantity>0),
  `status` TEXT COLLATE NOCASE NOT NULL CHECK (status IN('RESERVED','COMMITTED','RELEASED')) CONSTRAINT `ck_len_status` CHECK (length(`status`) <= 255),
  `idempotency_key` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_len_idempotency_key` CHECK (length(`idempotency_key`) <= 255),
  `created_at` INTEGER NOT NULL DEFAULT (CAST(unixepoch('subsec')*1000 AS INTEGER)),
  UNIQUE (`organization_id`, `feature_key`, `idempotency_key`)
) STRICT;
CREATE TABLE `usage_events` (
  `id` TEXT COLLATE NOCASE PRIMARY KEY CONSTRAINT `ck_len_id` CHECK (length(`id`) <= 36),
  `organization_id` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_len_organization_id` CHECK (length(`organization_id`) <= 36),
  `reservation_id` TEXT COLLATE NOCASE CONSTRAINT `ck_len_reservation_id` CHECK (length(`reservation_id`) <= 36),
  `event_key` TEXT COLLATE NOCASE NOT NULL UNIQUE CONSTRAINT `ck_len_event_key` CHECK (length(`event_key`) <= 255),
  `quantity` INTEGER NOT NULL CHECK (quantity>=0),
  `unit` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_len_unit` CHECK (length(`unit`) <= 255),
  `occurred_at` INTEGER NOT NULL DEFAULT (CAST(unixepoch('subsec')*1000 AS INTEGER))
) STRICT;
CREATE TABLE `security_events` (
  `id` INTEGER PRIMARY KEY AUTOINCREMENT,
  `organization_id` TEXT COLLATE NOCASE CONSTRAINT `ck_len_organization_id` CHECK (length(`organization_id`) <= 36),
  `actor_id` TEXT COLLATE NOCASE CONSTRAINT `ck_len_actor_id` CHECK (length(`actor_id`) <= 36),
  `ip_hash` TEXT COLLATE NOCASE CONSTRAINT `ck_len_ip_hash` CHECK (length(`ip_hash`) <= 64),
  `event_kind` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_len_event_kind` CHECK (length(`event_kind`) <= 255),
  `outcome` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_len_outcome` CHECK (length(`outcome`) <= 255),
  `occurred_at` INTEGER NOT NULL DEFAULT (CAST(unixepoch('subsec')*1000 AS INTEGER))
) STRICT;
CREATE TABLE `admin_actions` (
  `id` TEXT COLLATE NOCASE PRIMARY KEY CONSTRAINT `ck_len_id` CHECK (length(`id`) <= 36),
  `actor_id` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_len_actor_id` CHECK (length(`actor_id`) <= 36),
  `organization_id` TEXT COLLATE NOCASE CONSTRAINT `ck_len_organization_id` CHECK (length(`organization_id`) <= 36),
  `action` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_len_action` CHECK (length(`action`) <= 255),
  `justification` TEXT COLLATE NOCASE NOT NULL,
  `approved_by` TEXT COLLATE NOCASE CONSTRAINT `ck_len_approved_by` CHECK (length(`approved_by`) <= 36),
  `resulting_audit_event_id` INTEGER,
  `occurred_at` INTEGER NOT NULL DEFAULT (CAST(unixepoch('subsec')*1000 AS INTEGER))
) STRICT;
CREATE TABLE `model_evaluation_sets` (
  `id` TEXT COLLATE NOCASE PRIMARY KEY CONSTRAINT `ck_len_id` CHECK (length(`id`) <= 36),
  `name` TEXT COLLATE NOCASE NOT NULL UNIQUE CONSTRAINT `ck_len_name` CHECK (length(`name`) <= 255),
  `dataset_sha256` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_len_dataset_sha256` CHECK (length(`dataset_sha256`) <= 64),
  `license_note` TEXT COLLATE NOCASE NOT NULL,
  `manifest_object_key` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_len_manifest_object_key` CHECK (length(`manifest_object_key`) <= 255),
  `created_at` INTEGER NOT NULL DEFAULT (CAST(unixepoch('subsec')*1000 AS INTEGER))
) STRICT;
CREATE TABLE `model_evaluation_runs` (
  `id` TEXT COLLATE NOCASE PRIMARY KEY CONSTRAINT `ck_len_id` CHECK (length(`id`) <= 36),
  `model_version_id` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_len_model_version_id` CHECK (length(`model_version_id`) <= 36),
  `evaluation_set_id` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_len_evaluation_set_id` CHECK (length(`evaluation_set_id`) <= 36),
  `summary_metrics` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_json_summary_metrics` CHECK (json_valid(`summary_metrics`)),
  `acceptance_state` TEXT COLLATE NOCASE NOT NULL CHECK (acceptance_state IN('PENDING','PASSED','FAILED')) CONSTRAINT `ck_len_acceptance_state` CHECK (length(`acceptance_state`) <= 255),
  `reviewed_by` TEXT COLLATE NOCASE CONSTRAINT `ck_len_reviewed_by` CHECK (length(`reviewed_by`) <= 36),
  `created_at` INTEGER NOT NULL DEFAULT (CAST(unixepoch('subsec')*1000 AS INTEGER))
) STRICT;
CREATE TABLE `release_signoffs` (
  `id` TEXT COLLATE NOCASE PRIMARY KEY CONSTRAINT `ck_len_id` CHECK (length(`id`) <= 36),
  `build_sha` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_len_build_sha` CHECK (length(`build_sha`) <= 40),
  `gate_code` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_len_gate_code` CHECK (length(`gate_code`) <= 255),
  `state` TEXT COLLATE NOCASE NOT NULL CHECK (state IN('PENDING','PASS','FAIL','WAIVED')) CONSTRAINT `ck_len_state` CHECK (length(`state`) <= 255),
  `signed_by` TEXT COLLATE NOCASE CONSTRAINT `ck_len_signed_by` CHECK (length(`signed_by`) <= 36),
  `evidence_object_key` TEXT COLLATE NOCASE CONSTRAINT `ck_len_evidence_object_key` CHECK (length(`evidence_object_key`) <= 255),
  `signed_at` INTEGER,
  UNIQUE (`build_sha`, `gate_code`)
) STRICT;
CREATE TABLE `camera_transforms` (
  `id` TEXT COLLATE NOCASE PRIMARY KEY CONSTRAINT `ck_len_id` CHECK (length(`id`) <= 36),
  `video_id` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_len_video_id` CHECK (length(`video_id`) <= 36),
  `shot_id` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_len_shot_id` CHECK (length(`shot_id`) <= 36),
  `from_pts_us` INTEGER NOT NULL,
  `to_pts_us` INTEGER NOT NULL,
  `transform` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_json_transform` CHECK (json_valid(`transform`)),
  `reprojection_error_px` REAL,
  CHECK (to_pts_us>from_pts_us)
) STRICT;
CREATE TABLE `track_gaps` (
  `id` TEXT COLLATE NOCASE PRIMARY KEY CONSTRAINT `ck_len_id` CHECK (length(`id`) <= 36),
  `video_id` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_len_video_id` CHECK (length(`video_id`) <= 36),
  `track_id` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_len_track_id` CHECK (length(`track_id`) <= 36),
  `start_pts_us` INTEGER NOT NULL,
  `end_pts_us` INTEGER NOT NULL,
  `gap_reason` TEXT COLLATE NOCASE NOT NULL CHECK (gap_reason IN('OCCLUDED','OUT_OF_FRAME','CAMERA_CUT','DETECTION_FAILURE','UNKNOWN')) CONSTRAINT `ck_len_gap_reason` CHECK (length(`gap_reason`) <= 255),
  CHECK (end_pts_us>start_pts_us)
) STRICT;
CREATE TABLE `presence_intervals` (
  `id` TEXT COLLATE NOCASE PRIMARY KEY CONSTRAINT `ck_len_id` CHECK (length(`id`) <= 36),
  `video_id` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_len_video_id` CHECK (length(`video_id`) <= 36),
  `track_id` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_len_track_id` CHECK (length(`track_id`) <= 36),
  `start_pts_us` INTEGER NOT NULL,
  `end_pts_us` INTEGER NOT NULL,
  `observation_count` INTEGER NOT NULL CHECK (observation_count>=1),
  CHECK (end_pts_us>start_pts_us)
) STRICT;
CREATE TABLE `possession_episodes` (
  `id` TEXT COLLATE NOCASE PRIMARY KEY CONSTRAINT `ck_len_id` CHECK (length(`id`) <= 36),
  `video_id` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_len_video_id` CHECK (length(`video_id`) <= 36),
  `run_id` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_len_run_id` CHECK (length(`run_id`) <= 36),
  `player_id` TEXT COLLATE NOCASE CONSTRAINT `ck_len_player_id` CHECK (length(`player_id`) <= 36),
  `start_pts_us` INTEGER NOT NULL,
  `end_pts_us` INTEGER NOT NULL,
  `confidence` REAL CHECK (confidence BETWEEN 0 AND 1),
  `evidence_id` TEXT COLLATE NOCASE CONSTRAINT `ck_len_evidence_id` CHECK (length(`evidence_id`) <= 36),
  CHECK (end_pts_us>start_pts_us)
) STRICT;
CREATE TABLE `tactical_windows` (
  `id` TEXT COLLATE NOCASE PRIMARY KEY CONSTRAINT `ck_len_id` CHECK (length(`id`) <= 36),
  `video_id` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_len_video_id` CHECK (length(`video_id`) <= 36),
  `run_id` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_len_run_id` CHECK (length(`run_id`) <= 36),
  `from_pts_us` INTEGER NOT NULL,
  `to_pts_us` INTEGER NOT NULL,
  `kind` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_len_kind` CHECK (length(`kind`) <= 255),
  `coverage_ratio` REAL NOT NULL CHECK (coverage_ratio BETWEEN 0 AND 1),
  `metrics` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_json_metrics` CHECK (json_valid(`metrics`)),
  `evidence_state` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_enum_evidence_state` CHECK (`evidence_state` IN ('DETECTED', 'INFERRED', 'CONFIRMED', 'NOT_MEASURED')),
  `evidence_id` TEXT COLLATE NOCASE CONSTRAINT `ck_len_evidence_id` CHECK (length(`evidence_id`) <= 36),
  CHECK (to_pts_us>from_pts_us)
) STRICT;
CREATE TABLE `movement_segments` (
  `id` TEXT COLLATE NOCASE PRIMARY KEY CONSTRAINT `ck_len_id` CHECK (length(`id`) <= 36),
  `video_id` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_len_video_id` CHECK (length(`video_id`) <= 36),
  `track_id` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_len_track_id` CHECK (length(`track_id`) <= 36),
  `player_id` TEXT COLLATE NOCASE CONSTRAINT `ck_len_player_id` CHECK (length(`player_id`) <= 36),
  `start_pts_us` INTEGER NOT NULL,
  `end_pts_us` INTEGER NOT NULL,
  `movement_kind` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_len_movement_kind` CHECK (length(`movement_kind`) <= 255),
  `geometry_object_key` TEXT COLLATE NOCASE CONSTRAINT `ck_len_geometry_object_key` CHECK (length(`geometry_object_key`) <= 255),
  `confidence` REAL CHECK (confidence BETWEEN 0 AND 1),
  `evidence_state` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_enum_evidence_state` CHECK (`evidence_state` IN ('DETECTED', 'INFERRED', 'CONFIRMED', 'NOT_MEASURED')),
  CHECK (end_pts_us>start_pts_us)
) STRICT;
CREATE TABLE `identity_review_history` (
  `id` TEXT COLLATE NOCASE PRIMARY KEY CONSTRAINT `ck_len_id` CHECK (length(`id`) <= 36),
  `organization_id` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_len_organization_id` CHECK (length(`organization_id`) <= 36),
  `video_id` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_len_video_id` CHECK (length(`video_id`) <= 36),
  `track_id` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_len_track_id` CHECK (length(`track_id`) <= 36),
  `previous_decision_id` TEXT COLLATE NOCASE CONSTRAINT `ck_len_previous_decision_id` CHECK (length(`previous_decision_id`) <= 36),
  `new_decision_id` TEXT COLLATE NOCASE CONSTRAINT `ck_len_new_decision_id` CHECK (length(`new_decision_id`) <= 36),
  `reviewer_id` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_len_reviewer_id` CHECK (length(`reviewer_id`) <= 36),
  `decision` TEXT COLLATE NOCASE NOT NULL CHECK (decision IN('CONFIRM','REJECT','SPLIT','MERGE','UNRESOLVE')) CONSTRAINT `ck_len_decision` CHECK (length(`decision`) <= 255),
  `notes` TEXT COLLATE NOCASE,
  `created_at` INTEGER NOT NULL DEFAULT (CAST(unixepoch('subsec')*1000 AS INTEGER))
) STRICT;
CREATE TABLE `artifact_checks` (
  `id` TEXT COLLATE NOCASE PRIMARY KEY CONSTRAINT `ck_len_id` CHECK (length(`id`) <= 36),
  `artifact_id` TEXT COLLATE NOCASE NOT NULL CONSTRAINT `ck_len_artifact_id` CHECK (length(`artifact_id`) <= 36),
